z_grasp = 0.018; z_pre = 0.14
cands = {}
for n, h, bar in [("hand0", h0, barG), ("hand1", h1, barB)]:
    for yaw in (yaw_g, yaw_g - 180.0):
        pg = h.top_down([bar[0], bar[1], z_grasp], yaw)
        pp = h.top_down([bar[0], bar[1], z_pre], yaw)
        rs = h.ik_batch([pp, pg])
        out = []
        for rr in rs:
            if rr["reachable"]:
                s = rr["solutions"][0]
                out.append((True, round(s["pos_err_mm"],2), round(s["rot_err_deg"],2), round(s["limit_margin_rad"],3), s["singular"], np.round(s["q"],2).tolist()))
            else:
                out.append((False,))
        print(n, "yaw", round(yaw,1), "finger_yaw(pose)", round(h.finger_yaw(pg),1))
        for o in out: print("    ", o)
        cands[(n, round(yaw,1))] = (pp, pg, rs)

yaw0, yaw1 = yaw_g - 180.0, yaw_g
def poses(zz):
    return {"hand0": h0.top_down([barG[0], barG[1], zz], yaw0), "hand1": h1.top_down([barB[0], barB[1], zz], yaw1)}
for zp in (0.14, 0.12, 0.10):
